import contextlib
import io
import unittest

from textkit import rot
from textkit.cli import main


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class RotTest(unittest.TestCase):
    def test_rot13_known_values(self):
        self.assertEqual(rot.rot("Hello, World!", 13), "Uryyb, Jbeyq!")
        self.assertEqual(rot.rot("Uryyb, Jbeyq!", 13), "Hello, World!")

    def test_wraps_around(self):
        self.assertEqual(rot.rot("xyz", 3), "abc")
        self.assertEqual(rot.rot("XYZ", 1), "YZA")

    def test_keeps_case(self):
        self.assertEqual(rot.rot("aBcD", 1), "bCdE")

    def test_other_characters_unchanged(self):
        self.assertEqual(rot.rot("123 !?\n\t-_", 5), "123 !?\n\t-_")

    def test_non_ascii_letters_unchanged(self):
        self.assertEqual(rot.rot("é ß ü", 1), "é ß ü")

    def test_negative_n(self):
        self.assertEqual(rot.rot("abc", -1), "zab")
        self.assertEqual(rot.rot("zab", -1), "yza")

    def test_large_n(self):
        self.assertEqual(rot.rot("abc", 27), "bcd")
        self.assertEqual(rot.rot("abc", -53), "zab")
        self.assertEqual(rot.rot("abc", 26 * 1000), "abc")

    def test_zero_is_identity(self):
        self.assertEqual(rot.rot("Hello", 0), "Hello")

    def test_empty_text(self):
        self.assertEqual(rot.rot("", 13), "")

    def test_non_int_n_raises(self):
        for n in (1.5, 2.0, "1", None, True, False):
            with self.subTest(n=n), self.assertRaises(ValueError):
                rot.rot("abc", n)


class RotCommandTest(unittest.TestCase):
    def test_default_is_rot13(self):
        self.assertEqual(run("rot", "Hello, World!"), (0, "Uryyb, Jbeyq!\n", ""))

    def test_negative_n(self):
        self.assertEqual(run("rot", "abc", "--n", "-1"), (0, "zab\n", ""))

    def test_explicit_plus_sign(self):
        self.assertEqual(run("rot", "abc", "--n", "+1"), (0, "bcd\n", ""))

    def test_non_integer_n_exits_2(self):
        for value in ("1.5", "abc", "", "1e3"):
            with self.subTest(value=value):
                code, out, err = run("rot", "abc", "--n", value)
                self.assertEqual(code, 2)
                self.assertEqual(out, "")
                self.assertTrue(err.startswith("error:"))


if __name__ == "__main__":
    unittest.main()
